export async function paren(ok, s) { if (ok) /'/.test(s); const m = await import("../sim/situation.mjs"); if (ok) /'/.test(s); return m.situationOf; }
export async function brace(ok, s) { if (ok) {} /'/.test(s); const m = await import('../sim/kinds.mjs'); if (ok) {} /'/.test(s); return m.MOVER; }
export async function escaped() { return (await import('..\u002fsim\u002fspawn.mjs')).SPAWN; }
